```xUnit Test Cases
namespace U10_4

[Test]
public class SystemScalabilityTests
{
    [Fact]
    public void SystemShouldScaleTo10000Users()
    {
        var system = new System();
        var load = new Load(10000);
        system.Load(load);
        Assert.True(system.IsScalable);
    }

    [Fact]
    public void SystemResponseTimeShouldBeLessThan2SecondsForCriticalFunctionality()
    {
        var system = new System();
        var criticalFunctionality = new CriticalFunctionality();
        var load = new Load(10000);
        system.Load(load);
        var responseTime = system.MeasureResponseTime(criticalFunctionality);
        Assert.LessThan(responseTime, 2.0);
    }

    [Fact]
    public void SystemResponseTimeShouldBeLessThan4SecondsForOtherFunctions()
    {
        var system = new System();
        var otherFunction = new OtherFunction();
        var load = new Load(10000);
        system.Load(load);
        var responseTime = system.MeasureResponseTime(otherFunction);
        Assert.LessThan(responseTime, 4.0);
    }

    [Fact]
    public void SystemAvailabilityShouldBe99_999Percent()
    {
        var system = new System();
        var load = new Load(10000);
        system.Load(load);
        var availability = system.MeasureAvailability();
        Assert.Equal(availability, 99.999);
    }
}

namespace U10_4

[Test]
public class PatientRegistrationTests
{
    [Fact]
    public void PatientRegistrationShouldBePossible()
    {
        var system = new System();
        var patient = new Patient(PersonalInfo.Valid, MedicalInfo.Valid, GeneralInfo.Valid);
        var registration = system.RegisterPatient(patient);
        Assert.True(registration.IsSuccessful);
    }
}

namespace U10_4

[Test]
public class AdminFunctionalityTests
{
    [Fact]
    public void AdminShouldAddSpecialties()
    {
        var system = new System();
        var admin = new Admin();
        var specialties = new Specialties(Valid);
        admin.AddSpecialties(specialties);
        Assert.True(admin.IsSuccessful);
    }

    [Fact]
    public void AdminShouldRegisterDoctors()
    {
        var system = new System();
        var admin = new Admin();
        var doctors = new Doctors(Valid);
        admin.RegisterDoctors(doctors);
        Assert.True(admin.IsSuccessful);
    }
}
